<?php

namespace App\Support;

class TagNormaliser
{
    /**
     * @param  list<string>  $tags
     * @return list<string>
     */
    public function unique(array $tags): array
    {
        return array_values(
            collect($tags)
                ->map(fn (string $tag): string => trim($tag))
                ->reject(fn (string $tag): bool => $tag === '')
                ->uniqueStrict()
                ->all()
        );
    }
}

